#!/usr/bin/python3
"""Lossless regional cache packaging, preserving original compiler/input pins."""
import argparse,gzip,hashlib,importlib.util,json,pathlib,time
spec=importlib.util.spec_from_file_location('codec',pathlib.Path(__file__).with_name('regional-cache-codec.py'));codec=importlib.util.module_from_spec(spec);spec.loader.exec_module(codec)
p=argparse.ArgumentParser();p.add_argument('--input',required=True);p.add_argument('--repo',required=True);p.add_argument('--output',required=True);opts=p.parse_args();root=pathlib.Path(opts.repo);raw=gzip.decompress(pathlib.Path(opts.input).read_bytes());meta,body=codec.metadata(raw);sha=lambda b:hashlib.sha256(b).hexdigest();originalHashes=meta['sourceConsumerHashes'].copy();allowed={'game/src/spots/source-regional-terrain.js'}
