path='game/src/spots/regional-array-codec.js';meta['sourceConsumerHashes'][path]=sha((root/path).read_bytes());meta['transport']={'codec':'axis-xor-byteplanes-v2','packerSHA256':sha(pathlib.Path(__file__).read_bytes()),'helperSHA256':sha(pathlib.Path(__file__).with_name('regional-cache-codec.py').read_bytes()),'originalUncompressedSHA256':sha(raw),'originalNumericBlocksSHA256':sha(raw[body:]),'originalConsumerHashes':originalHashes,'basis':'Only the transport/loader changes; every original typed numeric bit and triangle order is retained. Original source/compiler/projection pins remain.'};packed=codec.encode(raw,meta);restored=codec.decode(packed);_,newbody=codec.metadata(restored);assert restored[newbody:]==raw[body:];output=pathlib.Path(opts.output);output.write_bytes(gzip.compress(packed,9,mtime=0));r={'path':output.name,'bytes':output.stat().st_size,'sha256':sha(output.read_bytes()),'uncompressedBytes':len(packed),'uncompressedSHA256':sha(packed),'originalInput':str(pathlib.Path(opts.input)),'restoredNumericBlocksSHA256':sha(restored[newbody:]),'originalNumericBlocksSHA256':sha(raw[body:]),'allOriginalNumericBytesIdentical':True,'originalCompressedBytes':pathlib.Path(opts.input).stat().st_size,'sourceDataSHA256':meta['sourceDataSHA256'],'nativeSceneDataSHA256':meta['nativeSceneDataSHA256'],'transport':meta['transport']};output.with_suffix(output.suffix+'.report.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r,indent=2))
